define(["jquery", "core/ajax", "core/notification"], function($, Ajax, Notification) {
    const getString = function(key) {
        return M.util.get_string(key, "mod_handraise");
    };

    const formatString = function(key, value) {
        return getString(key).replace("{$a}", value);
    };

    const renderStudent = function(root, state) {
        const button = root.find('[data-action="toggle-hand"]');
        if (!button.length) {
            return;
        }

        button.attr("aria-pressed", state.inqueue ? "true" : "false");
        button.find('[data-region="toggle-label"]').text(getString(state.inqueue ? "lowerhand" : "raisehand"));

        const status = root.find('[data-region="student-status"]');
        status.find('[data-region="position"]').remove();
        if (state.inqueue) {
            $("<div>", {
                class: "fw-semibold",
                "data-region": "position",
                text: formatString("positionlabel", state.position),
            }).prependTo(status);
        }
        status.find('[data-region="queue-count"]').text(formatString("queuecountlabel", state.queuecount));
    };

    const renderTeacher = function(root, state) {
        const list = root.find('[data-region="queue-list"]');
        if (!list.length) {
            return;
        }

        root.find('[data-region="teacher-count"]').text(state.queuecount);
        list.empty();

        if (!state.queue.length) {
            list.addClass("d-none");
            root.find('[data-region="empty-queue"]').removeClass("d-none");
            return;
        }

        list.removeClass("d-none");
        root.find('[data-region="empty-queue"]').addClass("d-none");

        state.queue.forEach(function(item) {
            const row = $("<div>", {
                class: "list-group-item d-flex align-items-center gap-3 py-3",
                "data-queue-id": item.id,
            });
            $("<div>", {
                class: "mod-handraise-position",
                "aria-hidden": "true",
                text: item.position,
            }).appendTo(row);

            const info = $("<div>", {class: "flex-grow-1 min-width-0"}).appendTo(row);
            $("<div>", {
                class: "fw-semibold text-truncate",
                text: item.fullname,
            }).appendTo(info);
            $("<div>", {
                class: "text-muted small",
                text: item.requestedat + " · " + item.waiting,
            }).appendTo(info);

            $("<button>", {
                type: "button",
                class: "btn btn-outline-success",
                "data-action": "serve",
                "data-queue-id": item.id,
                text: getString("serve"),
            }).appendTo(row);

            list.append(row);
        });
    };

    const render = function(root, state) {
        renderStudent(root, state);
        renderTeacher(root, state);
    };

    const call = function(methodname, args) {
        return Ajax.call([{
            methodname: methodname,
            args: args,
        }])[0];
    };

    const init = function(config) {
        const root = $('[data-region="handraise-root"][data-cmid="' + config.cmid + '"]');
        if (!root.length) {
            return;
        }

        let busy = false;
        let stopped = false;

        const refresh = function() {
            if (busy || stopped || document.hidden) {
                return;
            }
            call("mod_handraise_get_state", {cmid: config.cmid})
                .then(function(state) {
                    render(root, state);
                    return state;
                })
                .catch(Notification.exception);
        };

        root.on("click", '[data-action="toggle-hand"]', function() {
            if (busy) {
                return;
            }
            busy = true;
            const button = $(this).prop("disabled", true);
            call("mod_handraise_toggle_hand", {cmid: config.cmid})
                .then(function(state) {
                    render(root, state);
                    return state;
                })
                .catch(Notification.exception)
                .then(function() {
                    busy = false;
                    button.prop("disabled", false);
                });
        });

        root.on("click", '[data-action="serve"]', function() {
            if (busy) {
                return;
            }
            busy = true;
            const button = $(this).prop("disabled", true);
            call("mod_handraise_serve", {
                cmid: config.cmid,
                queueid: Number(button.attr("data-queue-id")),
            })
                .then(function(state) {
                    render(root, state);
                    return state;
                })
                .catch(Notification.exception)
                .then(function() {
                    busy = false;
                    button.prop("disabled", false);
                });
        });

        const timer = window.setInterval(refresh, Math.max(1000, config.pollinterval || 2000));
        $(window).on("beforeunload.mod_handraise", function() {
            stopped = true;
            window.clearInterval(timer);
        });
        document.addEventListener("visibilitychange", function() {
            if (!document.hidden) {
                refresh();
            }
        });
    };

    return {init: init};
});
